<template><section class="panel"><div class="panel-title"><h2>{{$t("患者档案")}}</h2><el-button v-if="canCreate" type="primary" icon="el-icon-plus" @click="openNew">{{$t("新建患者")}}</el-button></div><div class="toolbar"><el-input v-model.trim="q" clearable :placeholder="$t('姓名或病历号')" @keyup.enter.native="load"/><el-button @click="load">{{$t("查询")}}</el-button><span class="muted">{{$t("患者编号由系统生成，不允许手工编辑")}}</span></div><el-table v-loading="loading" :data="rows" stripe><el-table-column prop="case_number" :label="$t('病历号')" min-width="135"/><el-table-column prop="real_name" :label="$t('姓名')" min-width="100"/><el-table-column :formatter="localizedCell" prop="gender" :label="$t('性别')" width="85"/><el-table-column :label="$t('出生日期')" width="155"><template slot-scope="s">{{$t(date(s.row.birthdate))}}</template></el-table-column><el-table-column prop="phone" :label="$t('联系电话')" min-width="135"><template slot-scope="s">{{s.row.phone||'—'}}</template></el-table-column><el-table-column prop="home_address" :label="$t('地址')" min-width="160"><template slot-scope="s">{{s.row.home_address||'—'}}</template></el-table-column><el-table-column v-if="canCreate" :label="$t('操作')" width="90" fixed="right"><template slot-scope="s"><el-button type="text" @click="edit(s.row)">{{$t("编辑")}}</el-button></template></el-table-column></el-table><el-empty v-if="!loading&&!rows.length" :description="$t('暂无患者记录')"/><el-dialog :title="$t(editId?'编辑患者档案':'新建患者档案')" :visible.sync="dialog" width="610px" :close-on-click-modal="false" append-to-body><el-form ref="form" :model="form" label-position="top" :rules="rules"><div class="form-grid"><el-form-item :label="$t('姓名')" prop="name"><el-input v-model.trim="form.name" maxlength="80" :placeholder="$t('输入患者姓名')"/></el-form-item><el-form-item :label="$t('性别')" prop="gender"><el-select v-model="form.gender" class="full" :placeholder="$t('请选择')"><el-option v-for="v in ['男','女','未知']" :key="v" :label="$t(v)" :value="v"/></el-select></el-form-item><el-form-item :label="$t('出生日期')"><el-date-picker v-model="form.birthDate" value-format="yyyy-MM-dd" type="date" class="full" :placeholder="$t('选择日期')"/></el-form-item><el-form-item :label="$t('身份证号（选填）')"><el-input v-model.trim="form.identity" maxlength="18"/></el-form-item><el-form-item :label="$t('联系电话（选填）')"><el-input v-model.trim="form.phone" maxlength="32"/></el-form-item><el-form-item :label="$t('家庭住址（选填）')"><el-input v-model.trim="form.address" maxlength="255"/></el-form-item></div></el-form><span slot="footer" class="dialog-footer"><el-button @click="dialog=false">{{$t("取消编辑")}}</el-button><el-button type="primary" :loading="saving" :disabled="saving" @click="save">{{$t("确认保存")}}</el-button></span></el-dialog></section></template>
<script>import { t } from '../i18n';import api from '../api';export default{name:'Patients',props:['user'],data(){return{q:'',rows:[],loading:false,saving:false,dialog:false,editId:null,form:{name:'',gender:'',birthDate:'',identity:'',phone:'',address:''},rules:{name:[{required:true,message:()=>t('请填写姓名'),trigger:'blur'}],gender:[{required:true,message:()=>t('请选择性别'),trigger:'change'}]}}},computed:{canCreate(){return['ADMIN','REGISTRAR'].includes(this.user.role)}},created(){this.load()},methods:{openNew(){this.editId=null;this.form={name:'',gender:'',birthDate:'',identity:'',phone:'',address:''};this.dialog=true},edit(row){this.editId=row.id;this.form={name:row.real_name,gender:row.gender,birthDate:row.birthdate?String(row.birthdate).slice(0,10):'',identity:'',phone:row.phone||'',address:row.home_address||''};this.dialog=true},date(v){return v?String(v).slice(0,10):'—'},async load(){this.loading=true;try{this.rows=await api.get('/patients',{params:{q:this.q}})}catch(e){this.$message.error(e.message)}finally{this.loading=false}},save(){this.$refs.form.validate(async ok=>{if(!ok)return;try{await this.$confirm(this.editId?'确认保存本次患者档案的修改内容？':'确认创建患者档案？患者编号将自动分配。','保存确认',{type:'info'})}catch{return}this.saving=true;try{let p;if(this.editId){p=await api.put(`/patients/${this.editId}`,this.form);this.$message.success('档案已保存')}else{if(!this.form.requestId)this.form.requestId=Date.now().toString(36)+Math.random().toString(36).slice(2);p=await api.post('/patients',this.form);this.$message.success('创建成功：'+p.case_number)}this.dialog=false;this.form={name:'',gender:'',birthDate:'',identity:'',phone:'',address:''};await this.load()}catch(e){this.$message.error(e.message)}finally{this.saving=false}})}}}</script>
